mapper.select:
select a.id as `id`, a.title as `title`, c.name as `category`, a.create_time as `date`, a.status as `status`, GROUP_CONCAT(t.name SEPARATOR ',') AS `tags` from article as a left join article_tag as at on a.id = at.article_id left join tag as t on at.tag_id = t.id left join category as c on a.category_id = c.id
a.del_flag = 0 and a.create_time <= #{end}
and a.create_time >= #{begin}
and a.id = #{id}
and a.title like concat('%',#{title},'%')
and c.id = #{category}
and a.status = #{status}
group by a.id
having
tags like concat('%',#{tag},'%')
order by a.create_time desc
